// Node 18+ (ES module)
const res = await fetch('https://rpc-testnet.lumeus.dev/', {
  method: 'POST',
  headers: {
    Authorization: `Bearer ${process.env.LUMEUS_API_KEY}`,
    'Content-Type': 'application/json',
  },
  body: JSON.stringify({
    "jsonrpc": "2.0",
    "id": 1,
    "method": "getNetwork"
  }),
});
console.log(res.status, JSON.stringify(await res.json(), null, 2));
